<template>
  <div class="page-layout max-w-6xl mx-auto py-8 space-y-6">
    <header><p class="type-overline text-ink-muted">Practice library</p><h1 class="type-h1 text-ink">Documents</h1><p class="type-body text-ink-secondary mt-2">A tidy library for client, practice and prospect documents. Final PDFs remain read-only.</p></header>
    <div class="flex flex-wrap gap-2"><button v-for="item in filters" :key="item.value" type="button" class="button-secondary" :class="filter===item.value?'state-selected font-semibold':''" @click="filter=item.value">{{ item.label }}</button></div>
    <DocumentLibrary :documents="filtered" :loading="loading" :error="error" :archived="archived" title="Document library" description="Search, open and manage documents without losing historical records." @create="startCreate" @edit="edit" @view="view" @download="download" @archive="archive" @restore="restore" @update:archived="changeArchiveView" />
  </div>
  <teleport to="body">
    <div v-if="composerOpen" class="fixed inset-0 z-[70] bg-black/45 p-4 flex items-center justify-center" @click.self="requestClose"><section class="w-full max-w-3xl max-h-[92vh] overflow-hidden bg-surface-elevated border border-border rounded-panel shadow-overlay flex flex-col" role="dialog" aria-modal="true"><header class="p-6 border-b border-border-muted flex justify-between gap-4"><div><p class="type-overline text-ink-muted">{{ form.scope==='practice'?'Practice document':'Prospect document' }}</p><h2 class="text-h2 font-semibold">{{ finalised?'Document Finalised':(current?'Edit Document':'Create Document') }}</h2><p class="text-body-sm text-ink-secondary mt-1">{{ finalised?'The PDF is read-only and safely stored in Documents.':'Not linked to a client. Private reflections and supervision content are never included.' }}</p></div><button type="button" class="text-ink-muted" @click="requestClose">✕</button></header><div class="flex-1 overflow-auto"><div v-if="finalised" class="p-8"><div class="rounded-panel border border-state-success/20 bg-state-success-surface p-6"><p class="text-h3 font-semibold text-state-success">✓ PDF finalised and saved</p><p class="text-body-sm text-ink-secondary mt-2"><strong>{{ current.title }}</strong> is now read-only.</p></div><div class="mt-5 flex gap-2"><button class="button-primary" @click="view(current)">View PDF</button><button class="button-secondary" @click="download(current)">Download</button><button class="button-secondary" @click="closeComposer">Close</button></div></div><div v-else class="p-6 space-y-4"><div v-if="!current" class="grid md:grid-cols-2 gap-4"><label><span class="text-caption font-semibold">Scope</span><select v-model="form.scope" class="mt-1 w-full p-3 border border-border rounded-control bg-surface"><option value="practice">Practice</option><option value="prospect">Prospect / marketing</option></select></label><label><span class="text-caption font-semibold">Document type</span><select v-model="form.documentType" class="mt-1 w-full p-3 border border-border rounded-control bg-surface"><option value="agreement">Agreement</option><option value="consent_form">Consent form</option><option value="information_sheet">Information sheet</option><option value="marketing_letter">Marketing / prospect material</option><option value="other">Other</option></select></label></div><label class="block"><span class="text-caption font-semibold">Title</span><input v-model="form.title" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label><div class="grid md:grid-cols-2 gap-4"><label><span class="text-caption font-semibold">Recipient</span><input v-model="form.recipient" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label><label><span class="text-caption font-semibold">Purpose</span><input v-model="form.purpose" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label></div><label class="block"><span class="text-caption font-semibold">Document body</span><textarea v-model="form.body" rows="18" class="mt-1 w-full p-4 border border-border rounded-control bg-surface resize-y" /></label><div v-if="modalError" class="p-3 rounded-control bg-state-danger/10 text-state-danger">{{ modalError }}</div></div></div><footer v-if="!finalised" class="p-6 border-t border-border-muted flex flex-wrap items-center justify-between gap-3"><span class="text-caption" :class="dirty?'text-state-warning':'text-ink-muted'">{{ dirty?'Unsaved changes':saveMessage }}</span><div class="flex gap-2"><button class="button-secondary" :disabled="busy" @click="requestClose">Close</button><button class="button-secondary" :disabled="busy||!form.title.trim()" @click="preview">Preview</button><button class="button-secondary" :disabled="busy||!form.title.trim()" @click="save">Save Draft</button><button class="button-primary" :disabled="busy||!form.title.trim()||!form.body.trim()" @click="finalise">Finalise PDF</button></div></footer></section></div>
    <DocumentPreview v-if="previewOpen" :title="previewTitle" :display-url="previewUrl" :loading="previewLoading" :error="previewError" :downloadable="previewTarget?.status==='completed'" @close="closePreview" @download="download(previewTarget)" />
  </teleport>
</template>
<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue';
import { createUnscopedDocumentDraft,downloadDocument,finaliseDocument,listDocuments,previewDocument,setDocumentArchived,saveDocumentDraft,viewDocument } from '../lib/documents.js';
import DocumentLibrary from '../components/workspace/DocumentLibrary.vue';import DocumentPreview from '../components/workspace/DocumentPreview.vue';
const docs=ref([]),loading=ref(true),error=ref(''),filter=ref('all'),archived=ref(false),composerOpen=ref(false),current=ref(null),busy=ref(false),modalError=ref(''),saveMessage=ref('Not saved yet'),baseline=ref('');
const previewOpen=ref(false),previewUrl=ref(''),previewLoading=ref(false),previewError=ref(''),previewTarget=ref(null);const filters=[{value:'all',label:'All'},{value:'client',label:'Client Documents'},{value:'practice',label:'Practice Documents'},{value:'prospect',label:'Prospect / Marketing'}];const form=reactive({scope:'practice',documentType:'agreement',title:'',recipient:'',purpose:'',body:''});
const filtered=computed(()=>filter.value==='all'?docs.value:docs.value.filter(d=>d.scope===filter.value));const finalised=computed(()=>current.value?.status==='completed');const snapshot=()=>JSON.stringify(form);const dirty=computed(()=>!finalised.value&&baseline.value!==snapshot());const previewTitle=computed(()=>previewTarget.value?.title||current.value?.title||'Document');onMounted(refresh);onBeforeUnmount(closePreview);
async function refresh(){loading.value=true;error.value='';try{docs.value=await listDocuments({archived:archived.value})}catch(e){error.value=e.message||'Could not load documents.'}finally{loading.value=false}}
async function changeArchiveView(value){archived.value=value;await refresh()}
function startCreate(){current.value=null;Object.assign(form,{scope:'practice',documentType:'agreement',title:'',recipient:'',purpose:'',body:''});baseline.value=snapshot();composerOpen.value=true}
function edit(doc){current.value=doc;Object.assign(form,{scope:doc.scope,documentType:doc.documentType,title:doc.title,recipient:doc.recipient,purpose:doc.purpose,body:doc.content?.body||''});baseline.value=snapshot();composerOpen.value=true}
function changes(){return{title:form.title,documentType:form.documentType,recipient:form.recipient,purpose:form.purpose,content:{body:form.body}}}
async function persist(){current.value=current.value?await saveDocumentDraft(current.value,changes()):await createUnscopedDocumentDraft({scope:form.scope,...changes()});baseline.value=snapshot();saveMessage.value='Saved';await refresh();return current.value}
async function save(){busy.value=true;try{await persist()}catch(e){modalError.value=e.message}finally{busy.value=false}}
async function preview(){busy.value=true;previewError.value='';try{const d=await persist();previewTarget.value=d;previewOpen.value=true;previewLoading.value=true;const blob=await previewDocument(d);if(previewUrl.value?.startsWith('blob:'))URL.revokeObjectURL(previewUrl.value);previewUrl.value=URL.createObjectURL(blob)}catch(e){previewError.value=e.message}finally{previewLoading.value=false;busy.value=false}}
async function view(doc){previewTarget.value=doc;previewOpen.value=true;previewLoading.value=true;previewError.value='';try{previewUrl.value=await viewDocument(doc)}catch(e){previewError.value=e.message}finally{previewLoading.value=false}}
async function finalise(){if(!window.confirm('Finalise this document? The saved PDF will become read-only.'))return;busy.value=true;try{const d=await persist();current.value=await finaliseDocument(d);baseline.value=snapshot();await refresh()}catch(e){modalError.value=e.message}finally{busy.value=false}}
async function download(doc){if(!doc)return;try{await downloadDocument(doc)}catch(e){error.value=e.message}}
async function archive(doc){if(!window.confirm(`Archive “${doc.title}”? You can restore it later.`))return;await setDocumentArchived(doc,true);await refresh()}
async function restore(doc){await setDocumentArchived(doc,false);await refresh()}
function requestClose(){if(busy.value)return;if(dirty.value&&!window.confirm('You have unsaved changes. Close without saving?'))return;closeComposer()}
function closeComposer(){composerOpen.value=false;current.value=null;modalError.value=''}
function closePreview(){previewOpen.value=false;previewTarget.value=null;previewError.value='';if(previewUrl.value?.startsWith('blob:'))URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
</script>
